static st::Factory load_saved(const std::string&path,const curved::Packet&p){
    FILE*in=fopen(path.c_str(),"rb");need(in,"saved shared checkpoint");uint64_t h[8];need(fread(h,sizeof(h),1,in)==1&&h[0]==0x4746535452433031ULL&&h[1]==1&&h[2]==1&&h[4]==p.record.size()&&h[5]==sizeof(STTriangle)&&h[6]==sizeof(STCoefficient),"saved shared state header identity");st::Factory f;
    for(const auto&r:p.record)f.cell.push_back(r.cell);std::sort(f.cell.begin(),f.cell.end());f.cell.erase(std::unique(f.cell.begin(),f.cell.end()),f.cell.end());f.triangle.resize(h[4]);f.dof.resize(h[3]);f.coefficient.resize(h[3]);need(fread(f.triangle.data(),sizeof(STTriangle),f.triangle.size(),in)==f.triangle.size(),"saved fixed reference basis");std::vector<bool>seen(h[3]);
    for(size_t j=0;j<h[3];j++){uint64_t id[4];STCoefficient value;need(fread(id,sizeof(id),1,in)==1&&fread(&value,sizeof(value),1,in)==1&&id[0]<h[3]&&!seen[id[0]]&&id[3]==id[0]%4,"saved unique owner4 global coefficient");seen[id[0]]=true;f.dof[id[0]]={id[0],id[1],int(id[2]),int(id[3])};f.coefficient[id[0]]=value;for(int k=0;k<2;k++)need(std::isfinite(value.x[k])&&std::isfinite(value.v[k]),"saved finite x/v");}
    need(fgetc(in)==EOF,"complete saved shared checkpoint");fclose(in);
    for(size_t s=0;s<f.triangle.size();s++){const auto&t=f.triangle[s];need(t.n<=ST_MAX&&t.n>=15&&t.cell>=0&&size_t(t.cell)<f.cell.size()&&f.cell[t.cell]==p.record[s].cell,"saved physical cell/source identity");for(int a=0;a<3;a++)for(int k=0;k<2;k++)need(t.vertex[a][k]==p.record[s].triangle.geometry.x[a][k],"unchanged original reference vertex");for(int a=0;a<t.n;a++)need(t.id[a]>=0&&size_t(t.id[a])<f.dof.size(),"valid saved global DOF");}return f;
}
static rhs::Vec saved_raw_mass(const st::Factory&f,const std::vector<STPoint>&points){
    auto reference=f.triangle;for(auto&t:reference)for(int k=0;k<2;k++){t.bubble_shift[k]=0;for(int j=0;j<2;j++)t.bubble_encode[k][j]=k==j?1:0;}
    std::vector<std::vector<size_t>>by(reference.size());for(size_t i=0;i<points.size();i++)by[points[i].triangle].push_back(i);rhs::Vec raw(reference.size()*ST_MAX*ST_MAX);int failed=0;
    #pragma omp parallel for schedule(static) reduction(+:failed)
    for(size_t s=0;s<reference.size();s++){auto&t=reference[s];R*M=raw.data()+s*ST_MAX*ST_MAX;for(size_t i:by[s]){STJet N[ST_MAX];if(!st_shape(t,points[i],N)){failed++;continue;}R dm=R(points[i].weight)*points[i].rho;for(int a=0;a<t.n;a++)for(int b=0;b<t.n;b++)M[a*ST_MAX+b]+=dm*N[a].v*N[b].v;}}
    int global;MPI_Allreduce(&failed,&global,1,MPI_INT,MPI_SUM,MPI_COMM_WORLD);need(!global,"same saved raw mass basis");MPI_Allreduce(MPI_IN_PLACE,raw.data(),raw.size(),MPI_LONG_DOUBLE,MPI_SUM,MPI_COMM_WORLD);return raw;
}
