    struct Frozen {uint64_t triangle;double X,Y,weight,rho,U;};FILE*freeze=fopen((dest+"/frozen_physical_rank"+std::to_string(rank)+".bin").c_str(),"wb");need(freeze,"one-time export of OLD physical m/U before new EOS");uint64_t header[6]={0x47465346524f5a32ULL,2,1,uint64_t(points.size()),sizeof(Frozen),uint64_t(rank)};need(fwrite(header,sizeof(header),1,freeze)==1,"frozen physical U epoch/version/point count");
