    need(gp_cuda_evaluate(f.triangle.data(),f.triangle.size(),f.coefficient.data(),f.coefficient.size(),points.data(),points.size(),&physics,out.input.data(),out.gpu.data(),&out.kernel)==0,"native CUDA compatible pressure/thermal work");
