    R nu[24],error[24][2];for(int c=0;c<24;c++){nu[c]=metrics[c][0];error[c][0]=metrics[c][1];error[c][1]=metrics[c][2];}MPI_Allreduce(MPI_IN_PLACE,nu,24,MPI_LONG_DOUBLE,MPI_SUM,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,error,48,MPI_LONG_DOUBLE,MPI_MAX,MPI_COMM_WORLD);for(int c=0;c<24;c++){out.thermal[c].sum_nu=nu[c];out.thermal[c].max_volume_error=error[c][0];out.thermal[c].max_pressure_error=error[c][1];}R low[3]={out.minJ,out.minnu,out.minU},high[2]={out.force_difference,out.force_scale};MPI_Allreduce(MPI_IN_PLACE,low,3,MPI_LONG_DOUBLE,MPI_MIN,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,high,2,MPI_LONG_DOUBLE,MPI_MAX,MPI_COMM_WORLD);out.minJ=low[0];out.minnu=low[1];out.minU=low[2];out.force_difference=high[0];out.force_scale=high[1];return out;
