static bool constant_native_tests(const st::Factory&f,const std::vector<STPoint>&points,const State&s,const STPhysics&physics,int rank,int ranks,const std::string&dest){
    auto p=physics;p.gravity=0;auto fixture=s;bool pass=true;FILE*csv=nullptr;if(rank==0){csv=fopen((dest+"/constant_pressure_native.csv").c_str(),"w");need(csv,"native manufactured constant-pressure stress test");fprintf(csv,"constant,native_global_force_relative,native_pressure_error_relative,thermal_volume_identity_over_cA,CPU_CUDA_force_difference_over_cG\n");}
    for(double value:{.37*physics.P0,7.25*physics.P0,1.}){R constant=value;for(auto&t:fixture.thermal)t.mean_dp=constant-R(physics.P0);
        // A separate manufactured unit test, not replacement of the saved
        // physical U or a simulation trajectory. Both real states are const.
        for(size_t i=0;i<points.size();i++){fixture.input[i]=s.input[i];fixture.input[i].U=value*s.cpu[i].nu/(physics.gamma-1);fixture.input[i].mean_deltaP=value-physics.P0;}
        #pragma omp parallel for schedule(static)
        for(size_t i=0;i<points.size();i++)fixture.cpu[i]=gp_evaluate(f.triangle.data(),f.coefficient.data(),points[i],p,fixture.input[i]);
        need(gp_cuda_evaluate(f.triangle.data(),f.triangle.size(),f.coefficient.data(),f.coefficient.size(),points.data(),points.size(),&p,fixture.input.data(),fixture.gpu.data(),&fixture.kernel)==0,"native CUDA arbitrary constant pressure");
        auto load=assemble(f,points,fixture,p,rank,ranks,constant);R error[2]={},thermal[24]={};for(size_t i=0;i<points.size();i++){const auto&o=fixture.cpu[i].native;const auto&g=fixture.gpu[i].native;need(o.valid&&g.valid,"manufactured positive constant-pressure EOS");error[0]=std::max(error[0],fabsl(R(o.pressure)/constant-1));thermal[f.triangle[points[i].triangle].cell]+=o.Udot;for(int d=0;d<2;d++)for(int j=0;j<f.triangle[points[i].triangle].n;j++)error[1]=std::max(error[1],fabsl(R(o.force[d][j])-g.force[d][j])/(constant*s.geometry.derivative_scale));}
        MPI_Allreduce(MPI_IN_PLACE,error,2,MPI_LONG_DOUBLE,MPI_MAX,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,thermal,24,MPI_LONG_DOUBLE,MPI_SUM,MPI_COMM_WORLD);R force=0,heat=0;for(int d=0;d<2;d++)for(auto F:load.F[d])force=std::max(force,fabsl(F)/(constant*s.geometry.derivative_scale));for(int c=0;c<24;c++)heat=std::max(heat,fabsl(thermal[c]+constant*s.geometry.vdot[c])/(constant*s.thermal[c].A));pass=pass&&force<1e-11L&&error[0]<1e-11L&&heat<1e-11L&&error[1]<1e-11L;
        if(rank==0)fprintf(csv,"%.17g,%.21Lg,%.21Lg,%.21Lg,%.21Lg\n",value,force,error[0],heat,error[1]);
    }if(rank==0)fclose(csv);return pass;
}
static void compare_saved_load(const st::Factory&f,const std::vector<STPoint>&points,const State&s,const STPhysics&physics,const rhs::Mass&M,const Loads&load,const std::array<rhs::Vec,2>&a,bool initial,int rank,int ranks,const std::string&saved,const std::string&dest){
    rhs::Boundary boundary;auto oldF=rhs::forces(f,points,s.old,physics,rank,ranks,boundary);if(rank)return;std::array<rhs::Vec,2>old={rhs::Vec(f.dof.size()),rhs::Vec(f.dof.size())};
    if(initial){std::ifstream input(saved+"/shared_acceleration.csv");need(bool(input),"retain original SAVED initial acceleration");std::string line;std::getline(input,line);std::vector<bool>seen(f.dof.size());while(std::getline(input,line)){unsigned long long id;int owner;R ax,ay;need(sscanf(line.c_str(),"%llu,%d,%Lg,%Lg",&id,&owner,&ax,&ay)==4&&id<f.dof.size()&&!seen[id]&&owner==f.dof[id].owner,"saved original acceleration ownership");seen[id]=true;old[0][id]=ax;old[1][id]=ay;}for(bool v:seen)need(v,"complete saved original acceleration");}
    else for(int d=0;d<2;d++)old[d]=rhs::solve(M,oldF[d]).x;
    FILE*out=fopen((dest+"/old_new_loads.csv").c_str(),"w");need(out,"old/new loads and acceleration; separate immutable controls");fprintf(out,"id,old_Fx,old_Fy,new_Fx,new_Fy,old_ax,old_ay,new_ax,new_ay\n");for(size_t i=0;i<f.dof.size();i++)fprintf(out,"%zu,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg\n",i,oldF[0][i],oldF[1][i],load.F[0][i],load.F[1][i],old[0][i],old[1][i],a[0][i],a[1][i]);fclose(out);R residual=0;for(int d=0;d<2;d++){auto applied=M.apply(old[d]);for(size_t i=0;i<applied.size();i++)applied[i]-=oldF[d][i];residual=std::max(residual,sqrtl(rhs::dot(applied,applied)/rhs::dot(oldF[d],oldF[d])));}need(residual<1e-16L,"old acceleration still solves unchanged original mass/load equation");
}
